/* @lc app=leetcode id=2290 lang=kotlin */ class Solution { fun st(d: Array<IntArray>, r: Int, c: Int, v: Int) { d[r][c] = v } fun minimumObstacles(grid: Array<IntArray>): Int = Array(grid.size) { IntArray(grid[0].size) { Int.MAX_VALUE } }.also { it[0][0] = 0 }.let { d -> java.util.ArrayDeque<IntArray>().also { it.add(intArrayOf(0, 0)) }.let { dq -> generateSequence { dq.pollFirst() }.forEach { (r, c) -> listOf(r + 1 to c, r - 1 to c, r to c + 1, r to c - 1).filter { (a, b) -> a in grid.indices && b in grid[0].indices }.forEach { (a, b) -> (d[r][c] + grid[a][b]).let { nd -> if (nd < d[a][b]) st(d, a, b, nd).also { if (grid[a][b] == 0) dq.addFirst(intArrayOf(a, b)) else dq.addLast(intArrayOf(a, b)) } } } }.let { d[grid.size - 1][grid[0].size - 1] } } } }